// NormalizePlate returns the normalized plate (uppercase, alphanumeric only)
func NormalizePlate(plate string) string {
	var sb strings.Builder
	for _, r := range strings.ToUpper(plate) {
		if (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') {
			sb.WriteRune(r)
		}
	}
	return sb.String()
