// PreDistributeCommercials generates the commercial slots for date t (today or tomorrow)
// and saves them to the database planned_commercial_slots table.
func PreDistributeCommercials(t time.Time) {
	distMutex.Lock()
	defer distMutex.Unlock()

	if DB == nil {
		return
	}

	dateStr := t.Format("2006-01-02")
	LogLocal("INFO", "[Scheduler] Pre-distributing commercials for date %s", dateStr)

	// 1. Get schedule and block config for the day
	schedule, blockConfig, err := getScheduleAndBlockForDay(t)
	if err != nil || schedule == nil || blockConfig == nil {
		LogLocal("WARNING", "[Scheduler] No active schedule or block config for date %s. Skipping pre-distribution.", dateStr)
		return
	}

	// 2. Parse start and end times
	var sh, sm, ss, eh, em, es int
