func HandleReprocessVoicePackSonic(w http.ResponseWriter, r *http.Request) {
	idStr := r.URL.Query().Get("id")
	if idStr == "" {
		http.Redirect(w, r, "/dashboard/voice-packs?error=ID+do+conjunto+invalido", http.StatusSeeOther)
		return
	}

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	var baseDir string
	err := database.Pool.QueryRow(ctx, "SELECT base_directory FROM voice_packs WHERE id = $1", idStr).Scan(&baseDir)
	if err != nil || baseDir == "" {
		http.Redirect(w, r, "/dashboard/voice-packs?error=Conjunto+nao+encontrado", http.StatusSeeOther)
		return
	}

	entries, errRead := os.ReadDir(baseDir)
	if errRead != nil {
		http.Redirect(w, r, "/dashboard/voice-packs?error=Erro+ao+ler+diretorio+do+conjunto", http.StatusSeeOther)
		return
	}

	reprocessedCount := 0
	for _, entry := range entries {
		if !entry.IsDir() && strings.HasSuffix(strings.ToLower(entry.Name()), ".mp3") {
			filePath := filepath.Join(baseDir, entry.Name())
			if errMaster := utils.MasterizeAudio(filePath); errMaster == nil {
				reprocessedCount++
			}
