)

func main() {
	content, err := os.ReadFile("web/templates/stores.html")
	if err != nil {
		fmt.Printf("Error reading file: %v\n", err)
		return
	}

	htmlStr := string(content)
	// Find all <script> blocks
	scriptStart := 0
	for {
		startIdx := strings.Index(htmlStr[scriptStart:], "<script")
		if startIdx == -1 {
			break
		}
		startIdx += scriptStart
		endIdx := strings.Index(htmlStr[startIdx:], "</script>")
		if endIdx == -1 {
			fmt.Printf("⚠️ UNCLOSED <script> tag starting at char %d!\n", startIdx)
			break
		}
		endIdx += startIdx + 9
		scriptBlock := htmlStr[startIdx:endIdx]

		// Test executing this single script block wrapped in standard HTML
		testHTML := "<html><body>" + scriptBlock + "</body></html>"
		tmpl, errParse := template.New("test").Parse(testHTML)
		if errParse != nil {
			fmt.Printf("❌ PARSE ERROR in script at %d: %v\n", startIdx, errParse)
		} else {
			errExec := tmpl.Execute(io.Discard, map[string]interface{}{})
			if errExec != nil {
				fmt.Printf("❌ EXECUTE ERROR in script starting at char %d (len %d): %v\n", startIdx, len(scriptBlock), errExec)
				// Print script snippet
				if len(scriptBlock) > 200 {
					fmt.Printf("Snippet start: %s\nSnippet end: %s\n", scriptBlock[:100], scriptBlock[len(scriptBlock)-100:])
				} else {
					fmt.Printf("Snippet: %s\n", scriptBlock)
				}
			} else {
				fmt.Printf("✅ Script at %d executed OK!\n", startIdx)
			}
		}

		scriptStart = endIdx
	}
}
